import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.CBxkvBm_.js";const p=JSON.parse('{"title":"MSC Adams Multibody Dynamics & Mechanism Simulation","description":"Native compiler support for MSC Adams (.adm, .cmd) mechanism decks, 3D kinematics, Grübler mobility analysis, and bidirectional SIMPACK/Modelica projections in ModelScript.","frontmatter":{"title":"MSC Adams Multibody Dynamics & Mechanism Simulation","description":"Native compiler support for MSC Adams (.adm, .cmd) mechanism decks, 3D kinematics, Grübler mobility analysis, and bidirectional SIMPACK/Modelica projections in ModelScript."},"headers":[],"relativePath":"languages/adams.md","filePath":"languages/adams.md"}'),n={name:"languages/adams.md"};function l(d,t,o,r,c,g){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="msc-adams-multibody-dynamics" tabindex="-1">MSC Adams Multibody Dynamics <a class="header-anchor" href="#msc-adams-multibody-dynamics" aria-label="Permalink to &quot;MSC Adams Multibody Dynamics&quot;">​</a></h1><p>ModelScript features comprehensive, native support for <strong>MSC Adams</strong> (<code>.adm</code>, <code>.cmd</code>), the classic industrial standard for mechanical systems simulation and multibody dynamics (MBD). Engineers can parse legacy Adams View command files and solver datasets, perform Grübler-Kutzbach spatial mobility analysis, evaluate 3D joint constraint residuals, and project mechanisms to modern SIMPACK and Modelica formats.</p><hr><h2 id="capabilities-supported-formats" tabindex="-1">Capabilities &amp; Supported Formats <a class="header-anchor" href="#capabilities-supported-formats" aria-label="Permalink to &quot;Capabilities &amp; Supported Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Extension</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Adams Solver Dataset</strong></td><td style="text-align:left;"><code>.adm</code></td><td style="text-align:left;">Numerical dataset specifying rigid parts (<code>PART</code>), marker frames (<code>MARKER</code>), kinematic joints (<code>JOINT</code>), force elements (<code>SPRINGDAMPER</code>, <code>BUSHING</code>), and constraints.</td></tr><tr><td style="text-align:left;"><strong>Adams View Command File</strong></td><td style="text-align:left;"><code>.cmd</code></td><td style="text-align:left;">Interactive parametric command scripts defining mechanism geometry, design variables, and simulation runs.</td></tr></tbody></table><h3 id="key-architectural-features" tabindex="-1">Key Architectural Features <a class="header-anchor" href="#key-architectural-features" aria-label="Permalink to &quot;Key Architectural Features&quot;">​</a></h3><ul><li><strong>Lexer &amp; Parser:</strong><ul><li>Robust deck ingestion supporting scientific notation (<code>1.5D-03</code>), inline comments (<code>!</code>), line continuations (<code>...</code>), and block cards.</li><li>Lossless serialization back to standardized <code>.adm</code> solver format via <code>serializeAdams()</code>.</li></ul></li><li><strong>Spatial 3D Kinematics:</strong><ul><li>Full evaluation of Euler 3-1-3 and Tait-Bryan 1-2-3 rotation matrices.</li><li>Analytical joint constraint formulation for standard spatial joint primitives (Revolute, Spherical, Prismatic, Cylindrical, Planar, Universal).</li></ul></li><li><strong>Grübler-Kutzbach Mobility Analysis:</strong><ul><li>Calculates mechanism degrees of freedom ($M = 6(n - 1) - \\sum c_i$).</li><li>Identifies redundant kinematic constraints and overconstrained multi-loop linkages.</li></ul></li><li><strong>Multibody Linters (<code>M7301</code>–<code>M7310</code>):</strong><ul><li>Flags missing ground parts, dangling marker references, unphysical inertia tensors violating the triangle inequality ($I_{xx} + I_{yy} \\ge I_{zz}$), massless moving parts, and negative spring/damping parameters.</li></ul></li><li><strong>Cross-Domain Projections:</strong><ul><li><strong>SIMPACK MBD:</strong> Maps parts, markers, and spatial joints to SIMPACK <code>.spck</code> XML models.</li><li><strong>Modelica MultiBody:</strong> Synthesizes standard <code>Modelica.Mechanics.MultiBody</code> parts and joint components.</li></ul></li></ul><hr><h2 id="command-line-interface-msx-adams" tabindex="-1">Command Line Interface (<code>msx adams</code>) <a class="header-anchor" href="#command-line-interface-msx-adams" aria-label="Permalink to &quot;Command Line Interface (\`msx adams\`)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adams</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [files...] [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Description</th><th style="text-align:left;">Key Options</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>inspect</code></strong></td><td style="text-align:left;">Dumps part hierarchy, markers, joints, forces, and initial conditions.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>lint</code></strong></td><td style="text-align:left;">Runs structural validation, inertia verification, and kinematic sanity checks.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>mobility</code></strong></td><td style="text-align:left;">Evaluates spatial degrees of freedom and overconstrained loops.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>to-simpack</code></strong></td><td style="text-align:left;">Projects Adams mechanism to SIMPACK XML (<code>.spck</code>).</td><td style="text-align:left;"><code>--out=&lt;file.spck&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-modelica</code></strong></td><td style="text-align:left;">Projects Adams mechanism to <code>Modelica.Mechanics.MultiBody</code>.</td><td style="text-align:left;"><code>--out=&lt;file.mo&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-dae</code></strong></td><td style="text-align:left;">Lowers kinematic and dynamic momentum equations into <code>DAEBuilder</code> arena.</td><td style="text-align:left;">—</td></tr></tbody></table><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Calculate mechanism spatial degrees of freedom</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adams</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mobility</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FourBarLinkage.adm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Validate inertia tensors and marker references</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adams</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LandingGear.adm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Convert Adams dataset into SIMPACK XML format</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adams</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to-simpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RobotArm.adm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out=RobotArm.spck</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Lower multibody equations into ModelScript DAE arena</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adams</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to-dae</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ExcavatorMechanism.adm</span></span></code></pre></div><hr><h2 id="multibody-linters-diagnostic-rules" tabindex="-1">Multibody Linters &amp; Diagnostic Rules <a class="header-anchor" href="#multibody-linters-diagnostic-rules" aria-label="Permalink to &quot;Multibody Linters &amp; Diagnostic Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Identifier</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>M7301</code></strong></td><td style="text-align:left;"><code>dangling-part-reference</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Marker or joint references a part ID that does not exist in the dataset.</td></tr><tr><td style="text-align:left;"><strong><code>M7302</code></strong></td><td style="text-align:left;"><code>dangling-marker-reference</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Joint or force element references an undeclared marker ID.</td></tr><tr><td style="text-align:left;"><strong><code>M7303</code></strong></td><td style="text-align:left;"><code>non-physical-inertia-tensor</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Moments of inertia violate the triangle inequality ($I_{xx} + I_{yy} &lt; I_{zz}$) or are non-positive.</td></tr><tr><td style="text-align:left;"><strong><code>M7304</code></strong></td><td style="text-align:left;"><code>massless-moving-part</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Non-ground moving part has zero mass or zero principal inertia moments.</td></tr><tr><td style="text-align:left;"><strong><code>M7305</code></strong></td><td style="text-align:left;"><code>coincident-joint-markers</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Two markers on a joint are coincident in position and orientation, which may cause kinematic singularity.</td></tr><tr><td style="text-align:left;"><strong><code>M7306</code></strong></td><td style="text-align:left;"><code>overconstrained-mechanism</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Mobility analysis indicates overconstrained loops ($M &lt; 0$) requiring redundant constraint elimination.</td></tr><tr><td style="text-align:left;"><strong><code>M7307</code></strong></td><td style="text-align:left;"><code>negative-spring-stiffness</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Spring-damper element defines negative stiffness $K$ or negative damping coefficient $C$.</td></tr><tr><td style="text-align:left;"><strong><code>M7308</code></strong></td><td style="text-align:left;"><code>missing-ground-part</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Mechanism does not declare an inertial ground reference frame (<code>GROUND</code>).</td></tr><tr><td style="text-align:left;"><strong><code>M7309</code></strong></td><td style="text-align:left;"><code>unsupported-joint-primitive</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Joint card specifies an experimental or proprietary constraint type.</td></tr><tr><td style="text-align:left;"><strong><code>M7310</code></strong></td><td style="text-align:left;"><code>zero-length-link</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Distance between base and joint markers on a moving part is zero.</td></tr></tbody></table>`,16)])])}const h=e(n,[["render",l]]);export{p as __pageData,h as default};
